window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-98237d3a124c6143"]={"versions": [{"id": "FIG-98237d3a124c6143", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Funktionales Architektur- und Dekompositionsdiagramm (Blackbox-/Whitebox-Struktur einer logischen Software-Komponente) gemäß AUTOSAR-Konzept für ADAS &amp; Vehicle Motion Control (VMC).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Binnenstruktur des <code>Vehicle-MGR</code> (Vehicle Motion Manager SW-C) zur Entkopplung der fahrzeugagnostischen Assistenzebene (<code>ADAS-MGR</code>) von der fahrzeugspezifischen Aktor- und Sensorebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>Vehicle-MGR</code> dient als zentraler Vermittler, Bewegungsregler (Motion Controller) und Arbitrator. Er transformiert kinematische Sollvorgaben der Trajektorienplanung in kinetische Stellgrößen für Antriebsstrang, Bremse und Lenkung, konsolidiert Sensorrohdaten und meldet die Systemverfügbarkeit an übergeordnete Instanzen zurück.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Externe Schnittstellen (VFB Ports / Sender-Receiver Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Top-Down Sollwertpfad (<code>from ADAS-MGR</code>):</strong> Empfang kinematischer Sollgrößen (z. B. Sollbeschleunigung longitudinal, Sollverzögerung, Sollgierrate) über standardisierte VFB-Eingangsports.\n</li><li><strong>Bottom-Up Aktorik-Feedback (<code>from each actuator</code>):</strong> Empfang von Status- und Diagnoseinformationen aus den Domänensteuergeräten (Powertrain <code>PT</code>, Brake <code>BRK</code>, Steering <code>STR</code>).\n</li><li><strong>Bottom-Up Sensorik-Rohdaten (<code>from each vehicle Sensor</code>):</strong> Rohsignale von fahrzeugeigenen Sensoren (Raddrehzahlen, Inertialsensorik/IMU, Lenkwinkel).\n</li><li><strong>Top-Down Stellgrößen (<code>to each actuator</code>):</strong> Aktor-spezifische physikalische Stellbefehle (z. B. rad- oder achsindividuelle Drehmomentanforderungen für PT/BRK, Stellwinkel/-momente für STR).\n</li><li><strong>Bottom-Up Verfügbarkeitsrückmeldung (<code>to ADAS-MGR</code>):</strong> Aggregierter Verfügbarkeits- und Health-Status der Aktorik sowie normierte Fahrzeugdynamikgrößen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne Funktionsmodule des <code>Vehicle-MGR</code></h5>\n<ol class=\"fig-list\"><li><strong>Sollwert-Konditionierung &amp; Regelung (Stellpfad links):</strong>\n<ul class=\"fig-list\"><li><code>Change dimension for ACT target value</code>: Dimensions- und Koordinatentransformation kinematischer Vorgaben (Beschleunigung a_x, Verzögerung a_brk, Gierrate $\\dot{\\psi}$) in physikalische Stellgrößen.\n</li><li><code>Realizing ADAS application requirements</code>: Geschlossene Regelkreise (<code>Driving feedback controller</code>, <code>Braking feedback controller</code>, <code>Steering feedback controller</code>) zur Ausregelung dynamischer Soll-Ist-Abweichungen.\n</li><li><code>Torque Distribution PT and BRK</code>: Koordinierte Momentenaufteilung und Arbitrierung zwischen Antriebsstrang (PT) und Reib-/Rekuperationsbremse (BRK) inkl. Blending und radindividueller Stabilisierungseingriffe.\n</li></ul>\n</li><li><strong>Statusinterpretation &amp; Sensorverarbeitung (Rückmeldepfad rechts):</strong>\n<ul class=\"fig-list\"><li><code>Processing and normalization of vehicle sensor info.</code>: Aufbereitung, Filterung und Plausibilisierung von Sensorsignalen (u. a. Generierung einer konsistenten Fahrzeugreferenzgeschwindigkeit <code>Generate vehicle speed for display</code>).\n</li><li><code>Vehicle sensor status interpretation</code>: Signalqualitäts- und Plausibilitätsbewertung der Primärsensorik.\n</li><li><code>Actuator status interpretation</code>: Fehlererkennung und Zustandsanalyse der Teilsysteme (<code>PT, BRK, STR failure</code>) sowie Monitoring aktiver Subsystem-Eingriffe (<code>Stability control</code> wie ESC, ABS, TCS).\n</li><li><code>Notification actuator system availability for ADAS request</code>: Konsolidierung der Aktorzustände zu einem qualifizierten Verfügbarkeitsvektor für den <code>ADAS-MGR</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Downlink-Steuerkette (Zyklischer Regelpfad, typisch 5–10 ms)</h5>\n<ol class=\"fig-list\"><li><strong>Sollwert-Ingestion:</strong> <code>ADAS-MGR</code> übermittelt kinematische Führungsgrößen (a_x, $\\dot{\\psi}$).\n</li><li><strong>Dimensionstransformation:</strong> <code>Change dimension</code> berechnet benötigte Gesamtlängskraft und Giermoment unter Berücksichtigung fahrzeugphysikalischer Parameter (Masse, Radstand, Trägheitsmomente).\n</li><li><strong>Regelungsanpassung:</strong> Die <code>Feedback Controller</code> korrigieren die Stellgrößen anhand rückgeführter Ist-Zustände aus der Fahrzeugsensorik.\n</li><li><strong>Arbitrierung &amp; Momentenverteilung:</strong> <code>Torque Distribution</code> teilt das geforderte Längsmoment prioritätsgesteuert zwischen PT und BRK auf (z. B. Rekuperationsmaximierung vs. hydraulische Bremsdynamik).\n</li><li><strong>Aktor-Ansteuerung:</strong> Bereitstellung der individualisierten Stellbefehle an die Aktor-SW-Cs / BSW-Treiber.\n</li></ol>\n<h5 class=\"fig-section-h5\">Uplink-Diagnose- und Feedbackkette (Zyklisch &amp; Event-gesteuert)</h5>\n<ol class=\"fig-list\"><li><strong>Signalnormalisierung:</strong> Parallele Abtastung der Sensor- und Aktor-Rückmeldungen.\n</li><li><strong>Fehler- und Interventionsdetektion:</strong> <code>Actuator status interpretation</code> identifiziert Degradationen (z. B. Ausfall Lenkunterstützung, Begrenzung Bremsdruck) oder übersteuernde autonome Eingriffe (ESC aktiv).\n</li><li><strong>Verfügbarkeits-Arbitrierung:</strong> <code>Notification actuator system availability</code> bildet eine Zustandsmatrix der verfügbaren Systemdynamik (z. B. <em>Full Availability</em>, <em>Degraded / Limited Deceleration</em>, <em>Unavailable</em>).\n</li><li><strong>Status-Aktualisierung:</strong> Übertragung an <code>ADAS-MGR</code> zur dynamischen Anpassung der Trajektorienplanung oder Initiierung eines Safe-Stops (MRM).\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung &amp; Portabilität:</strong> Die Trennung stellt sicher, dass der <code>ADAS-MGR</code> vollständig frei von Aktor- und Antriebskonfigurationen (ICE, BEV, Hybrid, Allrad) implementiert werden kann. Fahrzeug-Derivatanpassungen verbleiben strikt im <code>Vehicle-MGR</code>.\n</li><li><strong>Echtzeit- und Latenzanforderungen:</strong> \n<ul class=\"fig-list\"><li>Die internen Regelschleifen (<code>Feedback Controller</code>, <code>Torque Distribution</code>) erfordern hochfrequente RTE-Task-Zyklen (1 ms … 10 ms).\n</li><li>Die Entkopplung erlaubt es, die Pfadplanung im <code>ADAS-MGR</code> mit niedrigerer Zykluszeit (20 ms … 50 ms) zu takten, da hochdynamische Störungen im <code>Vehicle-MGR</code> lokal ausgeregelt werden.\n</li></ul>\n</li><li><strong>API-Verträge &amp; Datenstrukturen:</strong>\n<ul class=\"fig-list\"><li>Sender-Receiver-Schnittstellen zwischen <code>ADAS-MGR</code> und <code>Vehicle-MGR</code> müssen strukturierte Datentypen mit Gültigkeitsattributen (Validitätsbits, Safety-Status, Sequenzzähler) nutzen.\n</li><li>Das Interface <code>Notification actuator system availability</code> fungiert als Handshake- und Freigabemechanismus für autonome Assistenzfunktionen.\n</li></ul>\n</li><li><strong>Funktionale Sicherheit (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Die Funktionen <code>Torque Distribution</code> und <code>Actuator status interpretation</code> tragen in der Regel die Einstufung <strong>ASIL D</strong> (Verhinderung unbeabsichtigter Beschleunigung/Verzögerung oder asymmetrischer Momentenverteilung).\n</li><li>Bei Aktorfehlern (<code>PT, BRK, STR failure</code>) oder transienten ESC-Eingriffen muss der <code>Vehicle-MGR</code> definierte Rückfallstrategien ohne Totzeit an die RTE und den <code>ADAS-MGR</code> propagieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f31edca4f3953fbe", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Funktionales Architektur- und Dekompositionsdiagramm (Blackbox-/Whitebox-Struktur einer logischen Software-Komponente) gemäß AUTOSAR-Konzept für ADAS &amp; Vehicle Motion Control (VMC).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Binnenstruktur des <code>Vehicle-MGR</code> (Vehicle Motion Manager SW-C) zur Entkopplung der fahrzeugagnostischen Assistenzebene (<code>ADAS-MGR</code>) von der fahrzeugspezifischen Aktor- und Sensorebene.\n</li><li><strong>Funktionale Einordnung:</strong> Der <code>Vehicle-MGR</code> dient als zentraler Vermittler, Bewegungsregler (Motion Controller) und Arbitrator. Er transformiert kinematische Sollvorgaben der Trajektorienplanung in kinetische Stellgrößen für Antriebsstrang, Bremse und Lenkung, konsolidiert Sensorrohdaten und meldet die Systemverfügbarkeit an übergeordnete Instanzen zurück.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Externe Schnittstellen (VFB Ports / Sender-Receiver Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Top-Down Sollwertpfad (<code>from ADAS-MGR</code>):</strong> Empfang kinematischer Sollgrößen (z. B. Sollbeschleunigung longitudinal, Sollverzögerung, Sollgierrate) über standardisierte VFB-Eingangsports.\n</li><li><strong>Bottom-Up Aktorik-Feedback (<code>from each actuator</code>):</strong> Empfang von Status- und Diagnoseinformationen aus den Domänensteuergeräten (Powertrain <code>PT</code>, Brake <code>BRK</code>, Steering <code>STR</code>).\n</li><li><strong>Bottom-Up Sensorik-Rohdaten (<code>from each vehicle Sensor</code>):</strong> Rohsignale von fahrzeugeigenen Sensoren (Raddrehzahlen, Inertialsensorik/IMU, Lenkwinkel).\n</li><li><strong>Top-Down Stellgrößen (<code>to each actuator</code>):</strong> Aktor-spezifische physikalische Stellbefehle (z. B. rad- oder achsindividuelle Drehmomentanforderungen für PT/BRK, Stellwinkel/-momente für STR).\n</li><li><strong>Bottom-Up Verfügbarkeitsrückmeldung (<code>to ADAS-MGR</code>):</strong> Aggregierter Verfügbarkeits- und Health-Status der Aktorik sowie normierte Fahrzeugdynamikgrößen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne Funktionsmodule des <code>Vehicle-MGR</code></h5>\n<ol class=\"fig-list\"><li><strong>Sollwert-Konditionierung &amp; Regelung (Stellpfad links):</strong>\n<ul class=\"fig-list\"><li><code>Change dimension for ACT target value</code>: Dimensions- und Koordinatentransformation kinematischer Vorgaben (Beschleunigung a_x, Verzögerung a_brk, Gierrate $\\dot{\\psi}$) in physikalische Stellgrößen.\n</li><li><code>Realizing ADAS application requirements</code>: Geschlossene Regelkreise (<code>Driving feedback controller</code>, <code>Braking feedback controller</code>, <code>Steering feedback controller</code>) zur Ausregelung dynamischer Soll-Ist-Abweichungen.\n</li><li><code>Torque Distribution PT and BRK</code>: Koordinierte Momentenaufteilung und Arbitrierung zwischen Antriebsstrang (PT) und Reib-/Rekuperationsbremse (BRK) inkl. Blending und radindividueller Stabilisierungseingriffe.\n</li></ul>\n</li><li><strong>Statusinterpretation &amp; Sensorverarbeitung (Rückmeldepfad rechts):</strong>\n<ul class=\"fig-list\"><li><code>Processing and normalization of vehicle sensor info.</code>: Aufbereitung, Filterung und Plausibilisierung von Sensorsignalen (u. a. Generierung einer konsistenten Fahrzeugreferenzgeschwindigkeit <code>Generate vehicle speed for display</code>).\n</li><li><code>Vehicle sensor status interpretation</code>: Signalqualitäts- und Plausibilitätsbewertung der Primärsensorik.\n</li><li><code>Actuator status interpretation</code>: Fehlererkennung und Zustandsanalyse der Teilsysteme (<code>PT, BRK, STR failure</code>) sowie Monitoring aktiver Subsystem-Eingriffe (<code>Stability control</code> wie ESC, ABS, TCS).\n</li><li><code>Notification actuator system availability for ADAS request</code>: Konsolidierung der Aktorzustände zu einem qualifizierten Verfügbarkeitsvektor für den <code>ADAS-MGR</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Downlink-Steuerkette (Zyklischer Regelpfad, typisch 5–10 ms)</h5>\n<ol class=\"fig-list\"><li><strong>Sollwert-Ingestion:</strong> <code>ADAS-MGR</code> übermittelt kinematische Führungsgrößen (a_x, $\\dot{\\psi}$).\n</li><li><strong>Dimensionstransformation:</strong> <code>Change dimension</code> berechnet benötigte Gesamtlängskraft und Giermoment unter Berücksichtigung fahrzeugphysikalischer Parameter (Masse, Radstand, Trägheitsmomente).\n</li><li><strong>Regelungsanpassung:</strong> Die <code>Feedback Controller</code> korrigieren die Stellgrößen anhand rückgeführter Ist-Zustände aus der Fahrzeugsensorik.\n</li><li><strong>Arbitrierung &amp; Momentenverteilung:</strong> <code>Torque Distribution</code> teilt das geforderte Längsmoment prioritätsgesteuert zwischen PT und BRK auf (z. B. Rekuperationsmaximierung vs. hydraulische Bremsdynamik).\n</li><li><strong>Aktor-Ansteuerung:</strong> Bereitstellung der individualisierten Stellbefehle an die Aktor-SW-Cs / BSW-Treiber.\n</li></ol>\n<h5 class=\"fig-section-h5\">Uplink-Diagnose- und Feedbackkette (Zyklisch &amp; Event-gesteuert)</h5>\n<ol class=\"fig-list\"><li><strong>Signalnormalisierung:</strong> Parallele Abtastung der Sensor- und Aktor-Rückmeldungen.\n</li><li><strong>Fehler- und Interventionsdetektion:</strong> <code>Actuator status interpretation</code> identifiziert Degradationen (z. B. Ausfall Lenkunterstützung, Begrenzung Bremsdruck) oder übersteuernde autonome Eingriffe (ESC aktiv).\n</li><li><strong>Verfügbarkeits-Arbitrierung:</strong> <code>Notification actuator system availability</code> bildet eine Zustandsmatrix der verfügbaren Systemdynamik (z. B. <em>Full Availability</em>, <em>Degraded / Limited Deceleration</em>, <em>Unavailable</em>).\n</li><li><strong>Status-Aktualisierung:</strong> Übertragung an <code>ADAS-MGR</code> zur dynamischen Anpassung der Trajektorienplanung oder Initiierung eines Safe-Stops (MRM).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung &amp; Portabilität:</strong> Die Trennung stellt sicher, dass der <code>ADAS-MGR</code> vollständig frei von Aktor- und Antriebskonfigurationen (ICE, BEV, Hybrid, Allrad) implementiert werden kann. Fahrzeug-Derivatanpassungen verbleiben strikt im <code>Vehicle-MGR</code>.\n</li><li><strong>Echtzeit- und Latenzanforderungen:</strong> \n<ul class=\"fig-list\"><li>Die internen Regelschleifen (<code>Feedback Controller</code>, <code>Torque Distribution</code>) erfordern hochfrequente RTE-Task-Zyklen (1 ms … 10 ms).\n</li><li>Die Entkopplung erlaubt es, die Pfadplanung im <code>ADAS-MGR</code> mit niedrigerer Zykluszeit (20 ms … 50 ms) zu takten, da hochdynamische Störungen im <code>Vehicle-MGR</code> lokal ausgeregelt werden.\n</li></ul>\n</li><li><strong>API-Verträge &amp; Datenstrukturen:</strong>\n<ul class=\"fig-list\"><li>Sender-Receiver-Schnittstellen zwischen <code>ADAS-MGR</code> und <code>Vehicle-MGR</code> müssen strukturierte Datentypen mit Gültigkeitsattributen (Validitätsbits, Safety-Status, Sequenzzähler) nutzen.\n</li><li>Das Interface <code>Notification actuator system availability</code> fungiert als Handshake- und Freigabemechanismus für autonome Assistenzfunktionen.\n</li></ul>\n</li><li><strong>Funktionale Sicherheit (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Die Funktionen <code>Torque Distribution</code> und <code>Actuator status interpretation</code> tragen in der Regel die Einstufung <strong>ASIL D</strong> (Verhinderung unbeabsichtigter Beschleunigung/Verzögerung oder asymmetrischer Momentenverteilung).\n</li><li>Bei Aktorfehlern (<code>PT, BRK, STR failure</code>) oder transienten ESC-Eingriffen muss der <code>Vehicle-MGR</code> definierte Rückfallstrategien ohne Totzeit an die RTE und den <code>ADAS-MGR</code> propagieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-98237d3a124c6143", "to": "FIG-f31edca4f3953fbe", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>Realizing ADAS application requirements</code>: Modulbeschriftung zu <code>Realizing ADAS Application requirements</code> angepasst (Großschreibung von „Application“).\n</li><li>Externe Schnittstellenbeschriftungen: Schreibweise von <code>to each actuator</code> zu <code>to each Actuator</code> sowie von <code>from each actuator</code> zu <code>from each Actuator</code> harmonisiert (Großschreibung von „Actuator“).\n</li></ul>"}]};
